#include <iostream>
#include <iomanip>
#include <cmath>

int main() {
    const double principal{1000.0};
    const double rate{0.05};
    const double rateFactor{1.0 + rate}; // Loop-invariant precomputed

    // Column headers
    std::cout << std::setw(4) << "Year" << std::setw(21) << "Amount on deposit" << '\n';

    // Sticky formatting: fixed-point with 2 decimal places
    std::cout << std::fixed << std::setprecision(2);

    for (unsigned int year{1}; year <= 5; ++year) {
        double amount = principal * std::pow(rateFactor, year);
        std::cout << std::setw(4) << year << std::setw(21) << amount << '\n';
    }

    return 0;
}

#include <iostream>

int main() {
    unsigned int counter{1};

    // do...while always executes at least once
    do {
        std::cout << counter << ' ';
        ++counter;
    } while (counter <= 5);

    std::cout << '\n';

    // Post-test demonstration with an initially false condition
    int value{100};
    do {
        std::cout << "Executed once even if false: " << value << '\n';
        value += 10;
    } while (value < 50);

    return 0;
}
